//! Per-workspace agent activity details; never store credentials or full document bodies.
use rusqlite::{params,Connection,OptionalExtension};
use serde_json::{json,Value};
fn bounded(v:&Value,key:&str)->Option<String>{v.get(key)?.as_str().map(|s|{let lower=s.to_lowercase();let has_label=["password","passwd","парол","secret","секрет","token","токен","api_key","api-key","apikey","authorization","bearer ","private key","sk-"].iter().any(|x|lower.contains(x));let long_hex=lower.split(|c:char|!c.is_ascii_hexdigit()).any(|run|run.len()>=32);if has_label||long_hex{"[скрыто: возможны секретные данные]".to_owned()}else{s.chars().take(500).collect()}})}
pub fn summarize(action:&str,request:&Value,response:&Value)->(Value,Value){
 let mut q=serde_json::Map::new();
 if matches!(action,"search"|"search_titles"|"rag"){if let Some(s)=bounded(request,"query"){q.insert("query".into(),s.into());}if let Some(s)=bounded(request,"mode"){if matches!(s.as_str(),"lexical"|"semantic"|"hybrid"){q.insert("mode".into(),s.into());}}}
 if matches!(action,"create"|"edit"){if let Some(title)=bounded(request,"title"){q.insert("title".into(),title.into());}}
 if action=="upload"{if let Some(name)=bounded(request,"name"){q.insert("name".into(),name.into());}if let Some(size)=request.get("size").and_then(Value::as_u64).filter(|n|*n<=10*1024*1024*1024){q.insert("size".into(),size.into());}}
 if matches!(action,"read"|"search"|"list"|"search_titles"){for key in ["offset","limit"]{if let Some(n)=request.get(key).and_then(Value::as_u64).filter(|n|*n<=1_000_000_000){q.insert(key.into(),n.into());}}}
 if matches!(action,"edit"|"upload"){if let Some(step)=request.get("action").and_then(Value::as_str).filter(|s|if action=="edit"{matches!(*s,"acquire"|"renew"|"release"|"commit")}else{matches!(*s,"begin"|"finish"|"cancel")}){q.insert("action".into(),step.into());}}
 if let Some(s)=request.get("object_id").and_then(Value::as_str).filter(|s|!s.is_empty()&&s.len()<=64&&s.bytes().all(|b|b.is_ascii_hexdigit()||b==b'-')){q.insert("object_id".into(),s.into());}
 let mut r=serde_json::Map::new();if action=="rag"{if let Some(answer)=bounded(response,"answer"){r.insert("answer".into(),answer.into());}}if let Some(n)=response.get("total").and_then(Value::as_u64){r.insert("total".into(),n.into());}else if let Some(n)=response.get("count").and_then(Value::as_u64){r.insert("count".into(),n.into());}else if let Some(items)=response.get("results").and_then(Value::as_array){r.insert("count".into(),items.len().into());}
 for key in ["ok","deleted","cancelled","replayed"]{if let Some(v)=response.get(key).and_then(Value::as_bool){r.insert(key.into(),v.into());}}
 if let Some(id)=response.get("id").and_then(Value::as_str).filter(|s|s.len()<=64&&s.bytes().all(|b|b.is_ascii_hexdigit()||b==b'-')){r.insert("id".into(),id.into());}
 (Value::Object(q),Value::Object(r))
}
fn prepare(db:&Connection)->Result<(),String>{
 db.execute_batch("CREATE TABLE IF NOT EXISTS agent_activity_details(event_id TEXT PRIMARY KEY,request TEXT,response TEXT,owner TEXT,epoch INTEGER);CREATE TABLE IF NOT EXISTS agent_activity_epochs(owner TEXT PRIMARY KEY,epoch INTEGER NOT NULL)").map_err(|e|e.to_string())?;
 let mut q=db.prepare("PRAGMA table_info(agent_activity_details)").map_err(|e|e.to_string())?;let cols=q.query_map([],|r|r.get::<_,String>(1)).map_err(|e|e.to_string())?.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?;drop(q);
 if !cols.iter().any(|x|x=="owner"){db.execute("ALTER TABLE agent_activity_details ADD COLUMN owner TEXT",[]).map_err(|e|e.to_string())?;}if !cols.iter().any(|x|x=="epoch"){db.execute("ALTER TABLE agent_activity_details ADD COLUMN epoch INTEGER",[]).map_err(|e|e.to_string())?;}Ok(())
}
fn validate(owner:&str,epoch:i64)->Result<(),String>{if uuid::Uuid::parse_str(owner).is_err()||epoch<0{return Err("invalid activity owner or epoch".into())}Ok(())}
pub fn sync_epoch(db:&Connection,owner:&str,epoch:i64)->Result<(),String>{validate(owner,epoch)?;prepare(db)?;let tx=db.unchecked_transaction().map_err(|e|e.to_string())?;tx.execute("INSERT INTO agent_activity_epochs(owner,epoch) VALUES(?,?) ON CONFLICT(owner) DO UPDATE SET epoch=MAX(epoch,excluded.epoch)",params![owner,epoch]).map_err(|e|e.to_string())?;let current:i64=tx.query_row("SELECT epoch FROM agent_activity_epochs WHERE owner=?",[owner],|r|r.get(0)).map_err(|e|e.to_string())?;if current!=epoch{return Err("stale activity epoch".into())}tx.execute("DELETE FROM agent_activity_details WHERE owner=? AND epoch<>?",params![owner,epoch]).map_err(|e|e.to_string())?;tx.commit().map_err(|e|e.to_string())}
pub fn save(db:&Connection,owner:&str,epoch:i64,id:&str,action:&str,request:&Value,response:&Value)->Result<(),String>{let(request,response)=summarize(action,request,response);save_summary(db,owner,epoch,id,action,&request,&response)}
pub fn save_summary(db:&Connection,owner:&str,epoch:i64,id:&str,action:&str,request:&Value,response:&Value)->Result<(),String>{validate(owner,epoch)?;if summarize(action,request,response)!=(request.clone(),response.clone()){return Err("invalid activity summary".into())}if uuid::Uuid::parse_str(id).is_err(){return Err("invalid activity id".into())}let q=request.to_string();let r=response.to_string();if q.len()>8192||r.len()>8192{return Err("activity details too large".into())}prepare(db)?;let tx=db.unchecked_transaction().map_err(|e|e.to_string())?;tx.execute("INSERT INTO agent_activity_epochs(owner,epoch) VALUES(?,?) ON CONFLICT(owner) DO NOTHING",params![owner,epoch]).map_err(|e|e.to_string())?;let current:i64=tx.query_row("SELECT epoch FROM agent_activity_epochs WHERE owner=?",[owner],|r|r.get(0)).map_err(|e|e.to_string())?;if current!=epoch{return Err("stale activity epoch".into())}tx.execute("INSERT INTO agent_activity_details(event_id,request,response,owner,epoch) VALUES(?,?,?,?,?)",params![id,q,r,owner,epoch]).map_err(|e|e.to_string())?;tx.commit().map_err(|e|e.to_string())}
pub fn get(db:&Connection,owner:&str,epoch:i64,id:&str)->Result<Option<Value>,String>{validate(owner,epoch)?;let ready:bool=db.query_row("SELECT (SELECT count(*) FROM sqlite_master WHERE type='table' AND name IN ('agent_activity_details','agent_activity_epochs'))=2",[],|r|r.get(0)).map_err(|e|e.to_string())?;if !ready{return Ok(None)}let row:Option<(String,String)>=db.query_row("SELECT d.request,d.response FROM agent_activity_details d JOIN agent_activity_epochs e ON e.owner=d.owner AND e.epoch=d.epoch WHERE d.event_id=? AND d.owner=? AND d.epoch=?",params![id,owner,epoch],|r|Ok((r.get(0)?,r.get(1)?))).optional().map_err(|e|e.to_string())?;row.map(|(q,r)|Ok(json!({"request":serde_json::from_str::<Value>(&q).map_err(|e|e.to_string())?,"response":serde_json::from_str::<Value>(&r).map_err(|e|e.to_string())?}))).transpose()}
pub fn copy_to(src:&Connection,dst:&Connection)->Result<(),String>{
 let exists:bool=src.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='agent_activity_details')",[],|r|r.get(0)).map_err(|e|e.to_string())?;if !exists{return Ok(())}prepare(dst)?;
 let mut cols=src.prepare("PRAGMA table_info(agent_activity_details)").map_err(|e|e.to_string())?;let names=cols.query_map([],|r|r.get::<_,String>(1)).map_err(|e|e.to_string())?.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?;drop(cols);let owned=names.iter().any(|x|x=="owner")&&names.iter().any(|x|x=="epoch");
 let sql=if owned{"SELECT event_id,request,response,owner,epoch FROM agent_activity_details"}else{"SELECT event_id,request,response,NULL,NULL FROM agent_activity_details"};let mut q=src.prepare(sql).map_err(|e|e.to_string())?;let rows=q.query_map([],|r|Ok((r.get::<_,String>(0)?,r.get::<_,Option<String>>(1)?,r.get::<_,Option<String>>(2)?,r.get::<_,Option<String>>(3)?,r.get::<_,Option<i64>>(4)?))).map_err(|e|e.to_string())?;for row in rows{let(id,request,response,owner,epoch)=row.map_err(|e|e.to_string())?;dst.execute("INSERT INTO agent_activity_details(event_id,request,response,owner,epoch) VALUES(?,?,?,?,?)",params![id,request,response,owner,epoch]).map_err(|e|e.to_string())?;}
 let has_epochs:bool=src.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type='table' AND name='agent_activity_epochs')",[],|r|r.get(0)).map_err(|e|e.to_string())?;if has_epochs{let mut q=src.prepare("SELECT owner,epoch FROM agent_activity_epochs").map_err(|e|e.to_string())?;for row in q.query_map([],|r|Ok((r.get::<_,String>(0)?,r.get::<_,i64>(1)?))).map_err(|e|e.to_string())?{let(owner,epoch)=row.map_err(|e|e.to_string())?;validate(&owner,epoch)?;dst.execute("INSERT OR REPLACE INTO agent_activity_epochs VALUES(?,?)",params![owner,epoch]).map_err(|e|e.to_string())?;}}Ok(())
}
#[cfg(test)] mod tests{use super::*;#[test]fn whitelist_limits_and_roundtrip(){let db=Connection::open_in_memory().unwrap();let(q,r)=summarize("search",&json!({"query":"q".repeat(1000),"token":"secret","text":"private"}),&json!({"results":[{"text":"secret"}],"token":"secret"}));assert_eq!(q["query"].as_str().unwrap().len(),500);assert_eq!(r["count"],1);assert!(!q.to_string().contains("secret"));assert!(!r.to_string().contains("secret"));save(&db,"0961fec4-5619-4115-a5ca-8352bcc841e8",1,"22d916fb-51a1-47bc-a29e-fc44a30aa451","search",&q,&r).unwrap();let got=get(&db,"0961fec4-5619-4115-a5ca-8352bcc841e8",1,"22d916fb-51a1-47bc-a29e-fc44a30aa451").unwrap().unwrap();assert_eq!(got["request"],q);assert_eq!(got["response"]["count"],1);assert!(save_summary(&db,"0961fec4-5619-4115-a5ca-8352bcc841e8",1,"4ec36bbb-9f8d-4e86-85fd-fc111cdf164c","search",&json!({"token":"secret"}),&json!({})).is_err());}}
#[cfg(test)] mod generation_tests {use super::*;
#[test]fn clear_only_own_namespace_and_reject_stale_writes(){let db=Connection::open_in_memory().unwrap();let a="0961fec4-5619-4115-a5ca-8352bcc841e8";let b="fa106677-7e17-4d55-a0ec-04041c2b5387";let x="eac8ecb2-6c67-496f-b328-0504a2a06c5c";let y="72cefe8e-53b0-4c3e-bb36-c6fa02b6df92";let q=json!({"query":"a"});let r=json!({});save_summary(&db,a,1,x,"search",&q,&r).unwrap();save_summary(&db,b,1,y,"search",&q,&r).unwrap();sync_epoch(&db,a,2).unwrap();assert!(get(&db,a,2,x).unwrap().is_none());assert!(get(&db,b,1,y).unwrap().is_some());assert!(save_summary(&db,a,1,x,"search",&q,&r).is_err());assert!(get(&db,a,1,x).unwrap().is_none());}}

#[cfg(test)] mod redaction_tests{use super::*;#[test]fn hides_typical_credentials_without_copying_secrets(){for query in ["token=abcd", "Authorization: Bearer hello", "password mypass", "ввод пароля 123", "ПАРОЛЬ 123", "key 0123456789abcdef0123456789abcdef", "sk-abcdef"]{let(q,_)=summarize("search",&json!({"query":query}),&json!({}));assert_eq!(q["query"],"[скрыто: возможны секретные данные]");}let(q,_)=summarize("search",&json!({"query":"машинное обучение"}),&json!({}));assert_eq!(q["query"],"машинное обучение");}}
#[cfg(test)] mod action_summary_tests {use super::*;
#[test]fn meaningful_details_for_agent_actions(){let id="4ec36bbb-9f8d-4e86-85fd-fc111cdf164c";let cases=[("read",json!({"object_id":id,"offset":100,"limit":20}),json!({"id":id,"total":200,"text":"must not retain"}),json!({"object_id":id,"offset":100,"limit":20})),("create",json!({"title":"Sample","text":"must not retain"}),json!({"id":id}),json!({"title":"Sample"})),("edit",json!({"object_id":id,"action":"commit","title":"Updated","lease":"secret","text":"must not retain"}),json!({"ok":true}),json!({"object_id":id,"action":"commit","title":"Updated"})),("delete",json!({"object_id":id}),json!({"deleted":true}),json!({"object_id":id})),("upload",json!({"action":"begin","name":"test.pdf","size":345,"digest":"secret"}),json!({"upload":"secret"}),json!({"action":"begin","name":"test.pdf","size":345})),("search",json!({"query":"find","mode":"semantic","offset":10,"limit":10}),json!({"total":20}),json!({"query":"find","mode":"semantic","offset":10,"limit":10})),("rag",json!({"query":"find"}),json!({"answer":"short","token":"secret"}),json!({"query":"find"}))];for(action,request,response,expected)in cases{let(q,r)=summarize(action,&request,&response);assert_eq!(q,expected,"{action}");assert!(!q.to_string().contains("secret"));assert!(!r.to_string().contains("secret"));assert!(!r.to_string().contains("must not retain"));}}
}

#[cfg(test)] mod object_id_tests {use super::*;#[test]fn keeps_valid_compact_id_but_rejects_arbitrary_input(){let id="0123456789abcdef0123456789abcdef";let(q,_)=summarize("read",&json!({"object_id":id}),&json!({}));assert_eq!(q["object_id"],id);let(q,_)=summarize("read",&json!({"object_id":"secret credential"}),&json!({}));assert!(q.get("object_id").is_none());}}

#[cfg(test)] mod catalog_activity_tests {use super::*;#[test]fn catalog_summary_keeps_paging_and_redacts_sensitive_text(){let(q,r)=summarize("list",&json!({"offset":2,"limit":4}),&json!({"total":10,"items":[{"title":"private"}]}));assert_eq!(q,json!({"offset":2,"limit":4}));assert_eq!(r,json!({"total":10}));let(q,_)=summarize("search_titles",&json!({"query":"password 123","limit":4}),&json!({}));assert_eq!(q["query"],"[скрыто: возможны секретные данные]");}}
